CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),event_type TEXT NOT NULL,actor_id TEXT,resource_type TEXT,resource_id TEXT,result_json TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,workspace_id TEXT,provider TEXT NOT NULL,event_id TEXT NOT NULL,payload_hash TEXT NOT NULL,status TEXT NOT NULL,received_at TEXT NOT NULL,UNIQUE(provider,event_id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),type TEXT NOT NULL,payload_ref TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','DEAD_LETTER','CANCELLED')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_records(key TEXT NOT NULL,workspace_id TEXT NOT NULL REFERENCES workspaces(id),action TEXT NOT NULL,resource_id TEXT,result_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(key,workspace_id,action));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_quota_snapshots(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),provider TEXT NOT NULL,period TEXT NOT NULL,requests INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER,output_tokens INTEGER,estimated_cost REAL,quota_state TEXT NOT NULL,created_at TEXT NOT NULL);
